import React, { useEffect, useMemo } from "react";
import ajax from "@/utils/ajax";
import app from "@/store/app";
import { AsyncButton, OperationList, ProTable, ProTableProps } from "@/components/custom";
import { useObserver } from "mobx-react-lite";
import { Button, Switch, Select, Space, Modal, Message } from "@arco-design/web-react";
import Store from './store';
import plugins from '@/store/plugins';
import _ from "lodash";

const SwitchBool = ({ id }: any) => {

    return useObserver(() => {
        const plugin = app.getPlugin(id);
        return (
            <Switch
                checked={plugin.isActive}
                onClick={() => {
                    // 判断是否
                    if(plugin.isActive){
                        // 移除插件
                        app.updatePlugin(id, { isActive: false })
                    }else {
                        // 添加插件
                        app.updatePlugin(id, { isActive: true })
                    }
                }}
            />
        )
    })
}

const UpdateVersion = ({ pluginId, PluginVersion, releaseVersion }: any) => {

    return useObserver(() => {
        const plugin = app.getPlugin(pluginId);

        return (
            <Select
                value={plugin.version || undefined}
                options={PluginVersion}
                allowClear
                // placeholder={`当前最新版本号：${releaseVersion}`}
                placeholder={`默认使用最新版本`}
                onChange={(value) => {
                    app.updatePlugin(pluginId, { version: value })
                }}
            />
        )
    })
}
const AppPlugins = () => {

    const store = useMemo(() => new Store(), []);

    const columns = useMemo(() => {
        
        return [
            {
                title: "插件名称",
                dataIndex: "name"
            },
            {
                title: "插件版本",
                dataIndex: "releaseVersion",
                width: 240,
                // tooltip: "如果不选择插件版本号，创建新版本时，将会以当前插件默认版本号进行构建",
                render: (id, item) => {
                    return (
                        <UpdateVersion {...item} />
                    )
                }
            },
            {
                title: "插件描述",
                dataIndex: "description"
            },
            {
                title: "是否启用",
                dataIndex: "pluginId",
                render: (id, item) => {
                    return <SwitchBool id={id} />
                }
            },
            {
                title: "操作",
                dataIndex: "id",
                render: (col, item) => {
                    return (
                        <OperationList 
                            list={[
                                {
                                    title: "删除",
                                    onClick: (e) => {
                                        Modal.confirm({
                                            title: "确认删除",
                                            content: `请确认是否删除【${item.name}】插件`,
                                            onOk: () => {
                                                return app.delPlugin(item.pluginId);
                                            }
                                        })
                                    }
                                }
                            ]} 
                        />
                    )
                }
            }
        ] as ProTableProps['columns']
    },[])



    const plugnColumns = useMemo(() => {

        return [
            {
                title: "插件名称",
                dataIndex: "name"
            },
            {
                title: "插件版本",
                dataIndex: "releaseVersion",
                width: 240,
                // tooltip: "如果不选择插件版本号，创建新版本时，将会以当前插件默认版本号进行构建",
                // render: (id, item) => {
                //     return (
                //         <UpdateVersion {...item} />
                //     )
                // }
            },
            {
                title: "插件描述",
                dataIndex: "description"
            },
            {
                title: "操作",
                dataIndex: "id",
                render: (col, item) => {
                    if(item.added){
                        return <Button type="text" disabled>已添加</Button>
                    }
                    return  <Button
                                type="primary"
                                onClick={() => {
                                    app.addPlugin(item);
                                }}
                            >添加</Button>
                    // return (
                    //     <OperationList
                    //         list={[
                    //             {
                    //                 title: "添加",
                    //                 onClick: (e) => {
                    //                     app.addPlugin(item);
                    //                 }
                    //             }
                    //         ]} 
                    //     />
                    // )
                }
            }
        ]
    },[])


    return useObserver(() => {
        
        useEffect(() => {
            plugins.init();
        },[])


        const pluginsList = useMemo(() => {
            if(!plugins.list) return [];
            // 过滤所有存在的插件
            return plugins.list.filter((o) => {
                return app.extraInfo.plugins[o.pluginId];
            })
        },[plugins.list, app.extraInfo])

        const list = useMemo(() => {
            if(!plugins.list) return [];
            return plugins.list.map((o) => {

                return {
                    ...o,
                    added: Boolean(app.extraInfo.plugins[o.pluginId])
                }
            })
        },[plugins.list, app.extraInfo])

        return (
            <div>
                <div className="flex items-center justify-between mb-2">
                    <div></div>
                    <Space>
                        <Button type="primary"
                            onClick={() => {
                                store.setVisible(true);
                            }}
                        >
                            新增插件
                        </Button>
                        <AsyncButton
                            type="primary"
                            onClick={() => {
                                return app.savaExtraInfo().then(()=> {
                                    Message.success("保存成功");
                                });
                            }}
                        >保存</AsyncButton>
                    </Space>
                </div>
                <ProTable
                    columns={columns}
                    data={pluginsList}
                    pagination={false}
                />
                <Modal visible={store.visible}
                    footer={null}
                    title="添加插件"
                    onCancel={() => {
                        store.setVisible(false);
                    }}
                    style={{ width: 1000 }}
                >
                    <ProTable
                        columns={plugnColumns}
                        data={list}
                        pagination={false}
                    />
                </Modal>
            </div>
        )
    })
}

export default AppPlugins;